function AddModal({collections,onClose,onAdd}) {
  const [url,setUrl] = useState('')
  const [title,setTitle] = useState('')
  const [description,setDescription] = useState('')
  const [collection,setCollection] = useState(collections[0].name)
  const [tags,setTags] = useState('')
  const valid = url.trim() && title.trim()
  const submit = e => { e.preventDefault(); if(!valid)return; let normalized=url.trim(); if(!/^https?:\/\//i.test(normalized)) normalized='https://'+normalized; let domain; try{domain=new URL(normalized).hostname.replace('www.','')}catch{domain=normalized}; onAdd({id:Date.now(),title:title.trim(),url:normalized,domain,description:description.trim()||'Saved for later.',tags:tags.split(',').map(t=>t.trim()).filter(Boolean),collection,favorite:false,added:'Just now',hue:'#2f7267',letter:title.trim()[0].toUpperCase()}) }
  return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="modal" role="dialog" aria-modal="true"><div className="modal-head"><div><span className="modal-icon"><BookmarkPlus size={20}/></span><div><h2>Save a bookmark</h2><p>Keep something worth coming back to.</p></div></div><button onClick={onClose}><X size={20}/></button></div><form onSubmit={submit}>
    <label>URL<input autoFocus type="text" placeholder="https://example.com" value={url} onChange={e=>setUrl(e.target.value)}/></label>
    <label>Title<input type="text" placeholder="What would you like to call it?" value={title} onChange={e=>setTitle(e.target.value)}/></label>
    <label>Description <small>Optional</small><textarea placeholder="A quick note about this page..." value={description} onChange={e=>setDescription(e.target.value)}/></label>
    <div className="form-row"><label>Collection<select value={collection} onChange={e=>setCollection(e.target.value)}>{collections.map(c=><option key={c.name}>{c.name}</option>)}</select></label><label>Tags <small>Comma separated</small><input placeholder="design, reading" value={tags} onChange={e=>setTags(e.target.value)}/></label></div>
    <div className="modal-foot"><button type="button" className="cancel" onClick={onClose}>Cancel</button><button className="save" disabled={!valid}><Bookmark size={17}/>Save bookmark</button></div>
  </form></div></div>
}

